// Extract incoming message from Meta WhatsApp Cloud API payload
const payload = $input.item.json.body || $input.item.json;
const entry = payload.entry?.[0];
const change = entry?.changes?.[0];
const value = change?.value;
const message = value?.messages?.[0];
const contact = value?.contacts?.[0];

if (!message || !message.text) {
  return []; // Ignore non-text or delivery receipts
}

const senderPhone = message.from; // e.g. 923001234567
const senderName = contact?.profile?.name || "Client";
const userText = message.text.body.trim();
const messageId = message.id;

return [{
  json: {
    senderPhone,
    senderName,
    userText,
    messageId,
    timestamp: new Date().toISOString()
  }
}];

const currentInput = $('Parse & Clean Inbound Message').item.json;
const historyItems = $input.all();

let conversationHistory = [];
if (Array.isArray(historyItems)) {
  for (const item of historyItems.reverse()) {
    const doc = item.json?.document?.fields;
    if (doc) {
      if (doc.incomingText?.stringValue) {
        conversationHistory.push({ role: "user", content: doc.incomingText.stringValue });
      }
      if (doc.replyText?.stringValue) {
        conversationHistory.push({ role: "assistant", content: doc.replyText.stringValue });
      }
    }
  }
}

const systemPrompt = `You are "Watech AI", the smart bilingual executive assistant for Watech Solutions in Pakistan. You represent an ecosystem of 3 premier sectors:\n\n1. REAL ESTATE:\n- Verified Residential & Commercial Plots, Houses, and Luxury Villas in DHA Lahore (Phase 5, 6, 7, 8, 9 Prism), Bahria Town, and Gulberg.\n- Price Ranges: 5 Marla Plots (PKR 90 Lac - 1.8 Cr), 10 Marla Luxury Villas (PKR 3.8 Cr - 5.5 Cr), 1 Kanal Mansions (PKR 7.5 Cr - 14 Cr).\n- Services: Transparent transfer verification, site visits scheduling, registry guidance.\n\n2. AUTHENTIC CHINIOTI WOOD FURNITURE:\n- 100% Seasoned Solid Sheesham (Rosewood) and Teak woodwork from master artisans of Chiniot, Punjab.\n- Offerings: Maharaja Carved Royal Bed Sets (PKR 280,000 - 450,000), 7-Seater Floral Living Sofas (PKR 220,000 - 350,000), 8-Seater Luxury Dining Suites (PKR 320,000 - 550,000).\n- Features: 10-Year Anti-Termite & Polish Guarantee, Nationwide Doorstep Delivery.\n\n3. SIGNATURE BANQUETS & EVENTS:\n- Verified Marquees & Grand Ballrooms in Lahore (Royal Palm, Defence Raya), Islamabad (Margalla View Club), and Karachi (Creek Heritage).\n- Catering Menus: Royal Desi Buffet (PKR 3,800/head), Signature Live BBQ (PKR 3,200/head), Continental Elite (PKR 4,500/head).\n- Capacities: 200 to 1,500 guests. Full event planning with stage decor and lighting.\n\nRULES:\n- Always greet respectfully (Assalam-o-Alaikum) when appropriate.\n- Answer in courteous Urdu/English (Roman Urdu is preferred for conversational warmth in Pakistan).\n- Keep replies under 120 words for WhatsApp readability.\n- If client asks for site visit or pricing, encourage locking a date or speaking with our direct line 0327-0831470.`;

const messages = [
  { role: "system", content: systemPrompt },
  ...conversationHistory,
  { role: "user", content: currentInput.userText }
];

return [{
  json: {
    senderPhone: currentInput.senderPhone,
    senderName: currentInput.senderName,
    userText: currentInput.userText,
    messagesPayload: messages
  }
}];

